tool_input.command:
python3 - <<'EOF'
p='src/Storefront/Pricing/PriceCache.cs'
s=open(p).read()
s=s.replace("""        get
        {
            lock (Gate)
            {
                return _lookups;
            }
        }
    }""","""        get => Interlocked.Read(ref _lookups);
    }""")
s=s.replace("""        _lookups++;

        lock""","""        // Counted outside the lock, so the increment must be atomic.
        Interlocked.Increment(ref _lookups);

        lock""")
s=s.replace("            _lookups = 0;","            Interlocked.Exchange(ref _lookups, 0);")
open(p,'w').write(s)
EOF
git diff --stat && for i in 1 2 3; do dotnet test --configuration Release --filter "FullyQualifiedName~PriceCacheTests" 2>&1 | tail -3; done
